import pandas as pd
import numpy as np

# Load raw financial data generated by script 1
df = pd.read_csv("data/raw_financials.csv")
df['Quarter'] = pd.to_datetime(df.index)
df = df.sort_values(by=['Ticker', 'Quarter'])

# Calculate operational metrics and ratios
df['OpMargin'] = df['Operating_Income'] / df['Total_Revenue']
df['CapEx_Ratio'] = df['CapEx'] / df['Total_Revenue']
df['RD_Ratio'] = df['RD_Expense'] / df['Total_Revenue']
df['Log_Assets'] = np.log(df['Total_Assets'])
df['Leverage'] = df['Total_Liabilities'] / df['Total_Equity']

# Create interaction term (CapEx Ratio * Software Dummy)
df['CapEx_x_Software'] = df['CapEx_Ratio'] * df['Is_Software']

# Clean out missing or incomplete quarterly entries
df = df.dropna(subset=['OpMargin', 'CapEx_Ratio', 'Log_Assets', 'Leverage'])

# Save processed panel
df.to_csv("data/panel_dataset_clean.csv", index=False)
print("Clean panel dataset saved to data/panel_dataset_clean.csv")